-- New project only: ztkiavqmbswyxkmddtno.
create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','employee','manager','owner','admin');
create type public.motorcycle_status as enum ('draft','available','reserved','sold','unavailable');
create type public.request_status as enum ('pending','reviewing','approved','rejected','completed');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text not null default '',phone text,preferred_language text not null default 'ar' check(preferred_language in ('ar','en')),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.clients(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users on delete cascade,display_name text not null default '',phone text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.user_roles(user_id uuid not null references auth.users on delete cascade,role public.app_role not null default 'customer',assigned_by uuid references auth.users on delete set null,created_at timestamptz default now(),primary key(user_id,role));
create table public.motorcycles(id uuid primary key default gen_random_uuid(),name text not null,model_year smallint check(model_year between 1900 and 2200),category text,price numeric(12,2) not null check(price>=0),currency char(3) not null default 'EGP',stock integer not null default 0 check(stock>=0),status public.motorcycle_status not null default 'draft',image_urls text[] not null default '{}',description text,created_by uuid references auth.users on delete set null,created_at timestamptz default now(),updated_at timestamptz default now());
create index motorcycles_status_price_idx on public.motorcycles(status,price);
create table public.customer_requests(id uuid primary key default gen_random_uuid(),client_user_id uuid not null references auth.users on delete restrict,motorcycle_id uuid references public.motorcycles on delete set null,requested_name text not null,requested_model_year smallint,budget numeric(12,2) check(budget>=0),notes text,status public.request_status not null default 'pending',created_at timestamptz default now(),updated_at timestamptz default now());
create index requests_user_date_idx on public.customer_requests(client_user_id,created_at desc);
create table public.favorites(user_id uuid not null references auth.users on delete cascade,motorcycle_id uuid not null references public.motorcycles on delete cascade,created_at timestamptz default now(),primary key(user_id,motorcycle_id));
create table public.contact_messages(id uuid primary key default gen_random_uuid(),sender_user_id uuid references auth.users on delete set null,name text not null,email text not null,message text not null check(length(message) between 1 and 10000),created_at timestamptz default now());
create table public.photo_assets(id uuid primary key default gen_random_uuid(),motorcycle_id uuid references public.motorcycles on delete set null,telegram_file_id text not null,telegram_message_id bigint,mime_type text,created_by uuid not null references auth.users on delete restrict,created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_user_id uuid references auth.users on delete set null,action text not null,table_name text not null,record_id text,created_at timestamptz default now());
create function public.has_any_role(roles public.app_role[]) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles r where r.user_id=(select auth.uid()) and r.role=any(roles));$$;
revoke all on function public.has_any_role(public.app_role[]) from public; grant execute on function public.has_any_role(public.app_role[]) to authenticated;
create function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,full_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),nullif(new.raw_user_meta_data->>'phone','')) on conflict do nothing; insert into public.clients(user_id,display_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),nullif(new.raw_user_meta_data->>'phone','')) on conflict do nothing; insert into public.user_roles(user_id,role) values(new.id,'customer') on conflict do nothing; return new; end$$;
revoke all on function public.handle_new_auth_user() from public,anon,authenticated;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_auth_user();
create function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now(); return new; end$$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at();
create trigger clients_updated before update on public.clients for each row execute function public.set_updated_at();
create trigger motorcycles_updated before update on public.motorcycles for each row execute function public.set_updated_at();
create trigger requests_updated before update on public.customer_requests for each row execute function public.set_updated_at();
do $$declare t text; begin foreach t in array array['profiles','clients','user_roles','motorcycles','customer_requests','favorites','contact_messages','photo_assets','audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end$$;
create policy profile_read on public.profiles for select to authenticated using(id=(select auth.uid()) or public.has_any_role(array['employee','manager','owner','admin']::public.app_role[]));
create policy profile_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy client_read on public.clients for select to authenticated using(user_id=(select auth.uid()) or public.has_any_role(array['employee','manager','owner','admin']::public.app_role[]));
create policy client_update on public.clients for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy role_read on public.user_roles for select to authenticated using(user_id=(select auth.uid()) or public.has_any_role(array['manager','owner','admin']::public.app_role[]));
create policy catalog_public_read on public.motorcycles for select to anon,authenticated using(status='available');
create policy catalog_staff on public.motorcycles for all to authenticated using(public.has_any_role(array['employee','manager','owner','admin']::public.app_role[])) with check(public.has_any_role(array['employee','manager','owner','admin']::public.app_role[]));
create policy request_read on public.customer_requests for select to authenticated using(client_user_id=(select auth.uid()) or public.has_any_role(array['employee','manager','owner','admin']::public.app_role[]));
create policy request_create on public.customer_requests for insert to authenticated with check(client_user_id=(select auth.uid()));
create policy request_staff on public.customer_requests for all to authenticated using(public.has_any_role(array['employee','manager','owner','admin']::public.app_role[])) with check(public.has_any_role(array['employee','manager','owner','admin']::public.app_role[]));
create policy favorite_self on public.favorites for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy contact_create on public.contact_messages for insert to anon,authenticated with check(sender_user_id is null or sender_user_id=(select auth.uid()));
create policy contact_staff on public.contact_messages for select to authenticated using(public.has_any_role(array['employee','manager','owner','admin']::public.app_role[]));
create policy photo_read on public.photo_assets for select to authenticated using(public.has_any_role(array['employee','manager','owner','admin']::public.app_role[]));
create policy photo_create on public.photo_assets for insert to authenticated with check(created_by=(select auth.uid()) and public.has_any_role(array['employee','manager','owner','admin']::public.app_role[]));
create policy audit_read on public.audit_logs for select to authenticated using(public.has_any_role(array['owner','admin']::public.app_role[]));
revoke all on all tables in schema public from anon,authenticated;
grant select on public.motorcycles to anon,authenticated;
grant select,update on public.profiles,public.clients to authenticated;
grant select on public.user_roles to authenticated;
grant select,insert,update,delete on public.motorcycles to authenticated;
grant select,insert,update,delete on public.customer_requests to authenticated;
grant select,insert,delete on public.favorites to authenticated;
grant insert on public.contact_messages to anon,authenticated;
grant select,insert on public.photo_assets to authenticated;
grant select on public.audit_logs to authenticated;
